{
  "$meta": {
    "extensible": false,
    "strictSet": true
  },
  "世界信息": {
    "$meta": {
      "extensible": false,
      "required": ["日期", "时间", "地点"]
    },
    "日期": ["2024年11月9日", "当前日期"],
    "时间": ["15:30", "当前时间，格式为 hh:mm"],
    "地点": ["老旧住宅区的家中", "当前场景地点"]
  },
  "穗秋生": {
    "$meta": {
      "extensible": false,
      "required": ["好感度", "害怕值", "依赖值", "身上的伤", "重要记忆"]
    },
    "好感度": [5, "[0-100]对{{user}}的爱意程度"],
    "害怕值": [95, "[0-100]对{{user}}的恐惧程度"],
    "依赖值": [100, "[0-100]对{{user}}的依赖程度"],
    "身上的伤": [["$__META_EXTENSIBLE__$", "额头有撞击的淤青", "头皮有裂伤正在流血", "左臂有抓痕", "右臂有烫伤旧痕", "膝盖有旧伤疤", "后背有鞭痕", "肋骨可能有裂纹"], "身体伤势列表，受伤时添加，痊愈时移除"],
    "重要记忆": [["$__META_EXTENSIBLE__$"], "发生重要事件时记录"]
  }
}

